  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'uniform_none', 'constraint_family': 'clamped_weights_reweight_only'})\n    # Uniform weights 1.0\n    weight_raw = feature_cache['objective'].new_ones(pair_count)\n    # Clamp weights to [0.1, 10.0] to avoid extreme values\n    weight = weight_raw.clamp(min=0.1, max=10.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'uniform_none', 'constraint_family': 'clamped_weights_reweight_only'})\n"
