{
  "name": "builder_all_pairs_gap_square",
  "intuition": "reweight all pairs by squared gap normalized for load balancing",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_square",
    "constraint_family": "fixed_pair_reweight_only"
  },
  "operators_used": [
    "all_pairs",
    "pow",
