    "index_add_",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_square'})\n    counts = torch.bincount(b_idx.to(torch.int64), minlength=int(objective.shape[0])).to(dtype=objective.dtype)\n    beta = float(extra.get('weight_beta', 1.0))\n    raw = torch.pow(gap.clamp(min=0), 2) * beta\n    denom = torch.zeros(int(objective.shape[0]), dtype=objective.dtype, device=objective.device)\n    denom.index_add_(0, b_idx, raw)\n    norm = denom[b_idx].clamp_min(1e-6)\n    weight = raw / norm\n    weight = weight * counts[b_idx].clamp_min(1.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_square'})\n"
}

{
  "name": "builder_all_pairs_gap_softmax_rescale_001",
  "intuition": "all_pairs topology with gap_softmax weights rescaled per instance for sharper weighting",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_softmax_rescaled",
    "constraint_family": "fixed_pair_reweight_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_softmax",
    "exp",
    "sum",
    "div"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax_rescaled'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    tau = float(extra.get('weight_tau', 1.0))\n    unnorm_w = 1.0 / (1.0 + ops.exp(-gap / tau))\n    # Compute sum per batch instance\n    b_idx_unique, inverse = ops.unique_inverse(b_idx)\n    sum_per_batch = ops.zeros_like(b_idx_unique, dtype=unnorm_w.dtype)\n    sum_per_batch = ops.scatter_add(sum_per_batch, inverse, unnorm_w)\n    # Normalize weights per batch\n    weight = unnorm_w / (sum_per_batch[inverse] + 1e-8)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax_rescaled'})\n"
}

